PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE concerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE,
            data TEXT,
            updated_at TEXT
        );
CREATE TABLE viewers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_key TEXT,
            members TEXT,
            desc TEXT,
            added_time TEXT
        );
CREATE TABLE id_projects (
            itemId TEXT PRIMARY KEY,
            title TEXT,
            url TEXT,
            added_time TEXT
        );
CREATE TABLE id_tickets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ticketId TEXT,
            itemId TEXT,
            info TEXT,
            FOREIGN KEY (itemId) REFERENCES id_projects (itemId) ON DELETE CASCADE
        );
CREATE TABLE tickets_sys (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            show_name TEXT,
            viewers TEXT,
            quantity INTEGER,
            price TEXT,
            status TEXT DEFAULT '待抢',
            notes TEXT,
            added_time TEXT
        , show_date TEXT, config_code TEXT);
CREATE TABLE known_patterns (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            show_name TEXT UNIQUE,
            added_time TEXT
        );
CREATE TABLE virtual_numbers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            phone TEXT,
            link TEXT,
            usage_count INTEGER DEFAULT 0,
            notes TEXT,
            added_time TEXT
        , sms_code TEXT DEFAULT '', cancellation_count INTEGER DEFAULT 0, mobile TEXT DEFAULT '', machine_code TEXT DEFAULT '');
CREATE TABLE mobile_library (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            phone TEXT UNIQUE
        , priority INTEGER DEFAULT 0);
CREATE TABLE quick_copy_tools (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            label TEXT NOT NULL,
            content TEXT NOT NULL,
            color TEXT DEFAULT '',
            bg_color TEXT DEFAULT ''
        );
CREATE TABLE show_schedules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            show_name TEXT NOT NULL,
            sale_time TEXT NOT NULL,
            added_time TEXT
        );
CREATE TABLE wechat_list (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            wechat_id TEXT UNIQUE,
            is_processed INTEGER DEFAULT 0,
            tag TEXT,
            inputter TEXT,
            added_time TEXT
        , remarks TEXT);
CREATE TABLE wechat_visit_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ip TEXT,
            user_agent TEXT,
            role TEXT,
            inputter TEXT,
            visit_time TEXT
        );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_vn_phone ON virtual_numbers(phone);
CREATE INDEX idx_vn_id_desc ON virtual_numbers(id DESC);
COMMIT;
